  kimi: {name:\'Kimi\', url:\'https://www.kimi.com/\'},
  zai: {name:\'Z.ai\', url:\'https://z.ai/\'}
};

let currentModel = null;

// === NAVIGATION ===
function showSection(id) {
  document.querySelectorAll(\'.content > div\').forEach(d => d.style.display = \'none\');
  document.getElementById(\'sec-\' + id).style.display = \'block\';
  document.querySelectorAll(\'.nav-item\').forEach(n => n.classList.remove(\'active\'));
  event.currentTarget?.classList.add(\'active\');
}

// === AI MODELS ===
function openAI(key) {
  currentModel = key;
  const m = AI_MODELS[key];
  window.open(m.url, \'_blank\');
  // Show context panel
  document.getElementById(\'ctxPanel\').style.display = \'block\';
  document.getElementById(\'ctxModelName\').textContent = m.name;
  // Load saved context
  const saved = localStorage.getItem(\'ctx_\' + key) || \'\';
  document.getElementById(\'ctxText\').value = saved;
  toast(\'Abriendo \' + m.name + \' en pestaña nueva\');
}

function reopenAI() {
  if (currentModel) window.open(AI_MODELS[currentModel].url, \'_blank\');
}

function saveContext() {
  if (!currentModel) return;
  localStorage.setItem(\'ctx_\' + currentModel, document.getElementById(\'ctxText\').value);
  toast(\'Contexto guardado para \' + AI_MODELS[currentModel].name);
}

function clearContext() {
  if (!currentModel) return;
  localStorage.removeItem(\'ctx_\' + currentModel);
  document.getElementById(\'ctxText\').value = \'\';
  toast(\'Contexto borrado\');
}

// === MEDIA PLAYER ===
function loadMedia() {
  const url = document.getElementById(\'mediaUrl\').value.trim();
  const container = document.getElementById(\'mediaContainer\');
  if (!url) return;

  if (url.includes(\'youtube.com\') || url.includes(\'youtu.be\')) {
    let vid = \'\';
    if (url.includes(\'v=\')) vid = url.split(\'v=\')[1].split(\'&\')[0];
    else if (url.includes(\'youtu.be/\')) vid = url.split(\'youtu.be/\')[1].split(\'?\')[0];
    container.innerHTML = `<iframe width="100%" height="200" src="https://www.youtube.com/embed/${vid}?rel=0&modestbranding=1" allowfullscreen style="border-radius:8px"></iframe>`;
  } else if (url.includes(\'spotify.com\')) {
    const embedUrl = url.replace(\'open.spotify.com\', \'open.spotify.com/embed\');
    container.innerHTML = `<iframe src="${embedUrl}" width="100%" height="152" frameborder="0" allowtransparency="true" allow="encrypted-media" style="border-radius:8px"></iframe>`;
