  const time = document.getElementById(\'alarmTime\').value;
  if (!time) return;
  document.getElementById(\'alarmStatus\').textContent = \'⏰ Alarma configurada para las \' + time;

  if (alarmInterval) clearInterval(alarmInterval);
  alarmInterval = setInterval(() => {
    const now = new Date();
    const h = String(now.getHours()).padStart(2,\'0\');
    const m = String(now.getMinutes()).padStart(2,\'0\');
    if (h + \':\' + m === time) {
      document.getElementById(\'alarmAudio\').play();
      toast(\'⏰ ¡ALARMA! Son las \' + time);
      document.getElementById(\'alarmStatus\').textContent = \'🔔 ¡SONANDO! Pulsa Cancelar para parar.\';
      clearInterval(alarmInterval);
    }
  }, 1000);
  toast(\'Alarma activada: \' + time);
}

function cancelAlarm() {
  if (alarmInterval) clearInterval(alarmInterval);
  document.getElementById(\'alarmAudio\').pause();
  document.getElementById(\'alarmAudio\').currentTime = 0;
  document.getElementById(\'alarmStatus\').textContent = \'Alarma cancelada.\';
